const PRINCIPLE_PALETTES = [
  { bg: "#EFEAE0", text: "#080B12", muted: "#334155", tagBg: "#080B12", tagText: "#EFEAE0", rotate: -4 },
  { bg: "#17181F", text: "#FFFFFF", muted: "#CBD5E1", tagBg: "#2456A4", tagText: "#FFFFFF", rotate: -2 },
  { bg: "#4024D6", text: "#FFFFFF", muted: "#E2E8F0", tagBg: "#D2FF1F", tagText: "#080B12", rotate: 0 },
  { bg: "#FF5414", text: "#FFFFFF", muted: "#FFF7ED", tagBg: "#080B12", tagText: "#FFFFFF", rotate: 2 },
  { bg: "#2456A4", text: "#FFFFFF", muted: "#DBEAFE", tagBg: "#F6F1E6", tagText: "#080B12", rotate: 4 },
];

export const fannedPrinciples = approach.map(([title, copy], idx) => {
  const step = process[idx];
  const palette = PRINCIPLE_PALETTES[idx] ?? PRINCIPLE_PALETTES[0]!;
  return {
    index: `0${idx + 1}`,
    title,
    copy,
    phase: step ? `${step[0]} — ${step[1]}` : pillars[0]![2],
    phaseName: step ? step[0] : "",
    palette,
  };
});

export const coreIndustries = industries;
export const corePillars = pillars;
